// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Log in an existing user
	// (POST /api/v1/auth/login)
	LoginUser(ctx context.Context, request LoginUserRequestObject) (LoginUserResponseObject, error)
	// Register a new user
	// (POST /api/v1/auth/register)
	RegisterUser(ctx context.Context, request RegisterUserRequestObject) (RegisterUserResponseObject, error)
	// Delete a product file
	// (DELETE /api/v1/files/{id})
	DeleteProductFile(ctx context.Context, request DeleteProductFileRequestObject) (DeleteProductFileResponseObject, error)
	// List hypotheses
	// (GET /api/v1/hypothesis)
	ListHypotheses(ctx context.Context, request ListHypothesesRequestObject) (ListHypothesesResponseObject, error)
	// Create hypothesis
	// (POST /api/v1/hypothesis)
	CreateHypothesis(ctx context.Context, request CreateHypothesisRequestObject) (CreateHypothesisResponseObject, error)
	// Delete hypothesis
	// (DELETE /api/v1/hypothesis/{id})
	DeleteHypothesis(ctx context.Context, request DeleteHypothesisRequestObject) (DeleteHypothesisResponseObject, error)
	// Get hypothesis
	// (GET /api/v1/hypothesis/{id})
	GetHypothesis(ctx context.Context, request GetHypothesisRequestObject) (GetHypothesisResponseObject, error)
	// Update hypothesis
	// (PATCH /api/v1/hypothesis/{id})
	UpdateHypothesis(ctx context.Context, request UpdateHypothesisRequestObject) (UpdateHypothesisResponseObject, error)
	// List product files attached to a hypothesis
	// (GET /api/v1/hypothesis/{id}/files)
	ListProductFiles(ctx context.Context, request ListProductFilesRequestObject) (ListProductFilesResponseObject, error)
	// Upload a product file attached to a hypothesis
	// (POST /api/v1/hypothesis/{id}/files)
	UploadProductFile(ctx context.Context, request UploadProductFileRequestObject) (UploadProductFileResponseObject, error)
	// Launch hypothesis
	// (POST /api/v1/hypothesis/{id}/launch)
	LaunchHypothesis(ctx context.Context, request LaunchHypothesisRequestObject) (LaunchHypothesisResponseObject, error)
	// Get hypothesis launch status
	// (GET /api/v1/hypothesis/{id}/launch-status)
	GetHypothesisLaunchStatus(ctx context.Context, request GetHypothesisLaunchStatusRequestObject) (GetHypothesisLaunchStatusResponseObject, error)
	// Get the product attached to a hypothesis
	// (GET /api/v1/hypothesis/{id}/product)
	GetHypothesisProduct(ctx context.Context, request GetHypothesisProductRequestObject) (GetHypothesisProductResponseObject, error)
	// Stop hypothesis
	// (POST /api/v1/hypothesis/{id}/stop)
	StopHypothesis(ctx context.Context, request StopHypothesisRequestObject) (StopHypothesisResponseObject, error)
	// Query the public persona dataset
	// (POST /api/v1/personas/query)
	QueryPersonas(ctx context.Context, request QueryPersonasRequestObject) (QueryPersonasResponseObject, error)
	// Create product
	// (POST /api/v1/product)
	CreateProduct(ctx context.Context, request CreateProductRequestObject) (CreateProductResponseObject, error)
	// Delete product
	// (DELETE /api/v1/product/{id})
	DeleteProduct(ctx context.Context, request DeleteProductRequestObject) (DeleteProductResponseObject, error)
	// Update product
	// (PATCH /api/v1/product/{id})
	UpdateProduct(ctx context.Context, request UpdateProductRequestObject) (UpdateProductResponseObject, error)
	// Get audience generation status for a product
	// (GET /api/v1/product/{id}/audience-generation)
	GetProductAudienceGenerationStatus(ctx context.Context, request GetProductAudienceGenerationStatusRequestObject) (GetProductAudienceGenerationStatusResponseObject, error)
	// Queue audience generation for a product
	// (POST /api/v1/product/{id}/audience-generation)
	QueueProductAudienceGeneration(ctx context.Context, request QueueProductAudienceGenerationRequestObject) (QueueProductAudienceGenerationResponseObject, error)
	// Retry failed audience generation for a product
	// (POST /api/v1/product/{id}/audience-generation/retry)
	RetryProductAudienceGeneration(ctx context.Context, request RetryProductAudienceGenerationRequestObject) (RetryProductAudienceGenerationResponseObject, error)
	// List audiences for a product
	// (GET /api/v1/product/{id}/audiences)
	ListProductAudiences(ctx context.Context, request ListProductAudiencesRequestObject) (ListProductAudiencesResponseObject, error)
	// Run the product feedback survey for every persona
	// (POST /api/v1/testing/product-feedback-survey)
	RunProductFeedbackSurvey(ctx context.Context, request RunProductFeedbackSurveyRequestObject) (RunProductFeedbackSurveyResponseObject, error)
	// List stored product feedback survey results
	// (GET /api/v1/testing/product-feedback-survey/results)
	ListProductFeedbackSurveyResults(ctx context.Context, request ListProductFeedbackSurveyResultsRequestObject) (ListProductFeedbackSurveyResultsResponseObject, error)
	// Get the Yandex confirmation-code authorization URL
	// (GET /api/v1/yandex-direct/authorization-url)
	GetYandexDirectAuthorizationURL(ctx context.Context, request GetYandexDirectAuthorizationURLRequestObject) (GetYandexDirectAuthorizationURLResponseObject, error)
	// Disconnect Yandex Direct and remove stored tokens
	// (DELETE /api/v1/yandex-direct/connection)
	DisconnectYandexDirect(ctx context.Context, request DisconnectYandexDirectRequestObject) (DisconnectYandexDirectResponseObject, error)
	// Get the current user's Yandex Direct connection status
	// (GET /api/v1/yandex-direct/connection)
	GetYandexDirectConnection(ctx context.Context, request GetYandexDirectConnectionRequestObject) (GetYandexDirectConnectionResponseObject, error)
	// Exchange a Yandex confirmation code and connect Yandex Direct
	// (POST /api/v1/yandex-direct/connection)
	ConnectYandexDirect(ctx context.Context, request ConnectYandexDirectRequestObject) (ConnectYandexDirectResponseObject, error)
	// Liveness probe
	// (GET /healthz)
	Healthz(ctx context.Context, request HealthzRequestObject) (HealthzResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

